import os
import hashlib
import hmac
import unicodedata
from pathlib import PurePosixPath
from typing import Optional, Dict, Tuple
import threading
import time

# Secure file sharing service with access control
SECRET_KEY = os.environ.get('HMAC_SECRET', '').encode()
if not SECRET_KEY:
    raise RuntimeError("HMAC_SECRET environment variable required")

class AccessControlList:
    """Thread-safe ACL manager"""
    def __init__(self):
        self._lock = threading.RLock()
        self._permissions: Dict[str, Dict[str, set]] = {}  # user -> {path -> perms}

    def grant(self, user_id: str, path: str, permissions: set):
        with self._lock:
            if user_id not in self._permissions:
                self._permissions[user_id] = {}
            normalized = self._normalize_path(path)
            self._permissions[user_id][normalized] = permissions

    def check_access(self, user_id: str, path: str, required_perm: str) -> bool:
        """Check if user has required permission on path"""
        with self._lock:
            if user_id not in self._permissions:
                return False
            user_perms = self._permissions[user_id]
            # Check exact match first
            if path in user_perms:
                return required_perm in user_perms[path]
            # Check parent directory permissions (inheritance)
            parts = path.rstrip('/').split('/')
            for i in range(len(parts) - 1, 0, -1):
                parent = '/'.join(parts[:i])
                if parent in user_perms:
                    if 'recursive' in user_perms[parent]:
                        return required_perm in user_perms[parent]
            return False

    def _normalize_path(self, path: str) -> str:
        """Normalize path for storage in ACL"""
        # Use NFC normalization for consistent Unicode representation
        normalized = unicodedata.normalize('NFC', path)
        # Resolve any . or .. components
        resolved = str(PurePosixPath(normalized))
        return resolved


class FileService:
    """Secure file access service"""

    def __init__(self, base_dir: str):
        self._base_dir = os.path.realpath(base_dir)
        self._acl = AccessControlList()
        self._token_cache: Dict[str, Tuple[str, float]] = {}
        self._cache_lock = threading.Lock()

    def create_access_token(self, user_id: str, path: str) -> str:
        """Create HMAC-signed access token for a specific path"""
        timestamp = str(int(time.time()))
        # Normalize path before signing
        canonical_path = self._canonicalize_request_path(path)
        payload = f"{user_id}:{canonical_path}:{timestamp}"
        signature = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
        token = f"{payload}:{signature}"
        return token

    def verify_access_token(self, token: str) -> Optional[Tuple[str, str]]:
        """Verify token and return (user_id, path) if valid"""
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, signature = parts
        expected_sig = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected_sig):
            return None
        payload_parts = payload.split(':')
        if len(payload_parts) != 3:
            return None
        user_id, path, timestamp = payload_parts
        # Token expires after 1 hour
        if int(time.time()) - int(timestamp) > 3600:
            return None
        return (user_id, path)

    def _canonicalize_request_path(self, path: str) -> str:
        """Canonicalize a user-supplied path for security checks.

        This applies Unicode normalization and resolves path components
        to prevent path traversal and Unicode confusion attacks.
        """
        # Step 1: Apply NFKC normalization to decompose compatibility characters
        # This handles cases like \uff0e (fullwidth period) -> .
        step1 = unicodedata.normalize('NFKC', path)

        # Step 2: Reject any path with null bytes
        if '\x00' in step1:
            raise ValueError("Null byte in path")

        # Step 3: Resolve path using PurePosixPath (handles .. and .)
        resolved = str(PurePosixPath('/' + step1.lstrip('/')))

        # Step 4: Ensure path doesn't escape base
        if '..' in resolved.split('/'):
            raise ValueError("Path traversal detected")

        return resolved

    def read_file(self, user_id: str, request_path: str) -> bytes:
        """Read a file with full access control checks.

        Security: validates path, checks ACL, verifies within base_dir.
        """
        # Canonicalize the requested path
        canonical = self._canonicalize_request_path(request_path)

        # Check ACL using canonical path
        if not self._acl.check_access(user_id, canonical, 'read'):
            raise PermissionError(f"Access denied")

        # Construct filesystem path and verify it's within base_dir
        # Apply NFC normalization for filesystem access
        fs_path = unicodedata.normalize('NFC', canonical)
        full_path = os.path.realpath(os.path.join(self._base_dir, fs_path.lstrip('/')))

        if not full_path.startswith(self._base_dir + os.sep):
            raise PermissionError("Path escapes base directory")

        if not os.path.isfile(full_path):
            raise FileNotFoundError("File not found")

        with open(full_path, 'rb') as f:
            return f.read()

    def grant_access(self, admin_id: str, target_user: str, path: str, perms: set):
        """Admin grants access to a user for a path"""
        # Verify admin has admin permission on the path
        canonical = self._canonicalize_request_path(path)
        if not self._acl.check_access(admin_id, canonical, 'admin'):
            raise PermissionError("Admin access required")
        self._acl.grant(target_user, canonical, perms)

    def setup_root_admin(self, admin_id: str):
        """Initialize root admin with full access"""
        self._acl.grant(admin_id, '/', {'read', 'write', 'admin', 'recursive'})


def handle_request(service: FileService, request: dict) -> dict:
    """Handle incoming API request"""
    action = request.get('action')
    user_id = request.get('user_id', '')

    if not user_id or not action:
        return {'error': 'Missing required fields'}

    try:
        if action == 'read':
            path = request.get('path', '')
            if not path:
                return {'error': 'Path required'}
            data = service.read_file(user_id, path)
            return {'status': 'ok', 'size': len(data)}

        elif action == 'grant':
            target = request.get('target_user', '')
            path = request.get('path', '')
            perms = set(request.get('permissions', []))
            if not target or not path:
                return {'error': 'Missing fields'}
            service.grant_access(user_id, target, path, perms)
            return {'status': 'ok'}

        elif action == 'token':
            path = request.get('path', '')
            if not path:
                return {'error': 'Path required'}
            token = service.create_access_token(user_id, path)
            return {'status': 'ok', 'token': token}

        else:
            return {'error': 'Unknown action'}

    except PermissionError as e:
        return {'error': str(e)}
    except (ValueError, FileNotFoundError) as e:
        return {'error': str(e)}
